//! The palette and its hue clamp -- SPEC-stella-tui-v2.md sections 3.1 and 3.2.
//!
//! GENERATED by `scripts/gen-tokens.py` from `design/tokens/stella-tokens.json`.
//! Do not edit this file. Edit the JSON and run `make tokens-update`.
//!
//! Every value is [`Color::Rgb`]; there are no indexed or named colours here,
//! because the clamp can only speak about channels. [`ALL`] pairs each token
//! with the [`Clamp`] its value is held to, and the tests at the bottom walk
//! that table -- so a new hex cannot enter the palette without declaring what
//! kind of colour it is, and the warm-drift predicates reject the declaration
//! that would kill the scheme.

use ratatui::style::Color;

// ── Clamp bounds ─────────────────────────────────────────────────

/// The green ratio a gold must clear, as a percentage of red.
///
/// The green ratio is the load-bearing half: below it the hue is orange, and orange on a near-black ground reads brown on cheap panels.
pub const GOLD_GREEN_PCT: u32 = 78;

/// The blue ceiling a resting gold must stay under, as a percentage of red.
pub const GOLD_BLUE_PCT: u32 = 35;

/// The blue ceiling for the *lift* -- the one gold that sits above
/// [`GOLD_BLUE_PCT`], used only for single-cell live indicators.
///
/// A recorded exception, not a relaxation. SPEC 3.2 states one clamp for
/// 'every color in the gold role', and SPEC 3.1's own gold_bright #F7D96B
/// does not satisfy it: b/r measures 107/247 = 0.433 against a stated
/// ceiling of 0.35. The spec contradicts itself. The canonical-token rule
/// forbids inventing a colour, so the value stands exactly as specified and
/// the ceiling that admits it is recorded here instead -- at 44, the
/// tightest whole percent that does (0.44 * 247 = 108.7, over the token's
/// 107; 0.43 * 247 = 106.2, under it). The bound is tight enough that any
/// drift bluer than the one token it was measured from fails. A maintainer
/// who wants 0.35 to hold everywhere should re-cut gold_bright; the number
/// to beat is in this paragraph.
pub const GOLD_LIFT_BLUE_PCT: u32 = 44;

